rows={}
def add(n,text,points,alerts,case,variation,qa,terms,links=()):
 rows['art-'+str(n)]=dict(simples=text,pontos=points,atencao=alerts,exemplo=case+' Variação: '+variation,prova=qa,termos=[dict(termo=t,significado=d) for t,d in terms],remissoes=[CPP,*links])
add(1,'O processo penal comum segue o CPP em todo o território brasileiro, com as ressalvas legais. A redação de 1941 precisa ser lida com a Constituição de 1988, legislação especial e decisões constitucionais; remissão histórica não cria competência atual.',
 ['Territorialidade processual: regra em todo o Brasil, com ressalvas de tratados e regras internacionais.', 'Justiça Militar possui processo próprio; o CPP não elimina esse regime.', 'Responsabilização de autoridades depende da Constituição vigente e das leis aplicáveis, não dos números constitucionais históricos transcritos no inciso II.'],
 ['Inciso IV menciona tribunal especial histórico: CF, art. 5º, XXXVII, veda juízo ou tribunal de exceção. Não ensinar sua existência atual.', 'Inciso V não restaura a Lei de Imprensa: ADPF 130 reconheceu a não recepção da Lei 5.250/1967. O parágrafo único não revive essa lei.'],
 'Uma questão afirma que crime praticado por publicação jornalística deve obrigatoriamente seguir a antiga Lei de Imprensa. A afirmação ignora a ADPF 130; identificar a infração e o regime atual aplicável.',
 'Em infração de competência militar, verificar o regime processual militar. A não recepção da Lei de Imprensa não revoga essa ressalva distinta.',
 ['A ressalva à Justiça Militar torna o CPP a única lei do processo militar? Não; há regime próprio.', 'O inciso V comprova a vigência atual da Lei 5.250/1967? Não; deve ser integrado à ADPF 130.'],
 [('Territorialidade processual','Regra de aplicação espacial do processo, distinta da extraterritorialidade da lei penal.')],
 ['https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm','https://noticias.stf.jus.br/postsnoticias/rejeitada-acao-em-que-advogado-condenado-por-extorsao-pedia-aplicacao-de-pena-da-lei-de-imprensa/'])
add(2,'A lei processual penal tem aplicação imediata aos atos futuros de um processo em andamento, preservada a validade dos atos praticados sob a lei anterior. O marco é o ato processual, sem invalidar automaticamente o que já foi regularmente realizado.',
 ['Aplicação imediata não exige que o processo comece depois da lei nova.', 'Atos anteriores regularmente praticados são preservados.', 'Distinguir norma puramente processual de conteúdo penal material ou misto.'],
 ['Não converter o art. 2º em autorização de retroatividade penal gravosa. Norma de conteúdo material exige exame da lei penal no tempo e da Constituição.'],
 'Uma audiência foi validamente realizada sob o procedimento anterior. Lei processual nova entra em vigor antes da próxima audiência: aplica-se aos próximos atos, sem repetir a anterior só pela mudança.',
 'Se a alteração amplia uma pena ou atinge direito penal material, a solução não decorre apenas do tempus regit actum; analisar irretroatividade gravosa e norma favorável.',
 ['O CPP determina refazer todo ato anterior quando muda a lei processual? Não; preserva a validade dos atos anteriores.', 'Processo já iniciado fica sempre submetido à lei antiga até terminar? Não; a regra processual é aplicação imediata aos atos futuros.'],
 [('Tempus regit actum','O ato processual é regido pela lei vigente quando praticado.')])
add(3,'A lei processual admite interpretação extensiva, aplicação analógica e suplemento dos princípios gerais do direito. São técnicas distintas, usadas com respeito à Constituição, ao contraditório e às demais garantias.',
 ['Interpretação extensiva esclarece alcance da norma existente.', 'Analogia integra lacuna por regra de situação semelhante.', 'Princípios gerais suplementam a disciplina processual, sem licença para atuação arbitrária.'],
 ['Analogia processual não autoriza criar crime, agravar pena ou afastar garantia fundamental. Não transferir a permissão do CPP à analogia penal incriminadora.'],
 'Surge lacuna sobre um ato processual e propõe-se regra de situação semelhante: verificar compatibilidade, finalidade e garantias antes de aplicar analogia.',
 'Se alguém tenta usar analogia para transformar conduta não tipificada em crime, o art. 3º do CPP não serve de fundamento.',
 ['Extensiva e analogia são sinônimos? Não; uma interpreta o alcance da regra e a outra integra lacuna.', 'A analogia admitida pelo CPP permite inventar novo crime? Não; há legalidade penal e limites constitucionais.'],
 [('Analogia','Integração de lacuna pela disciplina de hipótese semelhante.')])
add('3-a','O processo tem estrutura acusatória: investigar e acusar não são funções assumidas pelo juiz. A imparcialidade impede iniciativa judicial na investigação e substituição da atividade probatória da acusação.',
 ['Separar investigação, acusação e julgamento.', 'Juiz não pode atuar como investigador ou substituir a acusação.', 'STF admite diligências suplementares pontuais, nos limites legalmente autorizados, para dúvida relevante ao julgamento do mérito.'],
 ['Não ensinar nem juiz investigador nem proibição absoluta de toda diligência judicial. A ressalva do STF é delimitada; não autoriza construir uma acusação faltante.'],
 'O juiz decide iniciar por conta própria uma investigação para descobrir quem cometeu um crime. Isso conflita com a estrutura acusatória.',
 'Diligência suplementar pontual para esclarecer dúvida relevante no julgamento, autorizada em lei e com garantias, não equivale a iniciar investigação de ofício.',
 ['O juiz pode assumir a função de investigar porque busca a verdade? Não; art. 3º-A impede essa iniciativa.', 'Toda diligência suplementar judicial é proibida pelo STF? Não; existe ressalva pontual e legalmente delimitada.'],
 [('Sistema acusatório','Separação funcional que protege a imparcialidade do julgamento.')],[STF,CJF])
add('3-b','O juiz das garantias controla a legalidade da investigação e resguarda direitos cuja restrição exige autorização judicial. Não conduz a investigação, não assume a acusação e não decide a condenação.',
 ['I–IV: receber comunicações da prisão e da instauração da investigação, controlar o flagrante e proteger os direitos da pessoa presa.', 'V–VIII: decidir requerimentos de prisão/cautelares, sua prorrogação, substituição ou revogação; produção antecipada urgente e não repetível; prorrogação do inquérito de investigado preso.', 'IX–X: trancar inquérito sem fundamento razoável e requisitar informações/documentos/laudos sobre o andamento.', 'XI: decidir interceptação, afastamento de sigilos, busca domiciliar, acesso a informações sigilosas e outros meios que restrinjam direitos fundamentais, com requisitos próprios.', 'XII–XIII: habeas corpus antes do oferecimento da acusação e incidente de insanidade mental.', 'XIV: a menção literal ao recebimento não define o marco atual; pelo STF a competência cessa com o OFERECIMENTO.', 'XV–XVIII: assegurar acesso defensivo aos elementos produzidos, ressalvadas diligências em andamento; admitir assistente técnico; homologar ANPP/colaboração formalizados na investigação; outras matérias inerentes ao controle do caput.', '§1º: Lei 15.358/2026 passou a prever audiência de custódia por videoconferência em até 24 horas para flagrante ou mandado provisório, com MP e defesa e requisitos do art. 310.', '§2º: STF admite novas prorrogações fundamentadas por elementos concretos e complexidade; vencimento do prazo não revoga automaticamente a preventiva. O juízo deve avaliar seus fundamentos.'],
 ['Atualização de 2026: não repetir como redação atual a antiga proibição absoluta de videoconferência. A disciplina de 2023/CNJ 562 deve ser distinguida da nova redação, com direitos e requisitos do art. 310 preservados.', 'A Lei 15.358 está submetida às ADIs 7952, 7956, 7957 e 7958. Notícia de audiência pública não é decisão de mérito nem prova de suspensão. Não certificada aqui a inexistência de decisões posteriores em cada ação.', 'Contraditório das cautelares e prova antecipada: STF admitiu dispensar audiência quando houver risco ao processo ou diferi-la por necessidade; exige fundamento, não supressão genérica da defesa.'],
 'Durante o inquérito, a polícia requer busca domiciliar: o juiz controla requisitos e fundamenta a decisão, sem assumir a condução da investigação. Encerrado o prazo do inquérito com preso, eventual prorrogação exige motivos concretos e controle judicial da custódia.',
 'Depois de oferecida a denúncia, não atribuir o recebimento ao juiz das garantias por leitura isolada do inciso XIV. Para custódia realizada em 2026, conferir a redação nova e o art. 310, sem aplicar automaticamente a frase de 2019.',
 ['O juiz das garantias pode condenar ao concluir o inquérito? Não; exerce controle investigativo e proteção de direitos.', 'O vencimento do prazo do §2º sempre solta automaticamente o preso? Não; a interpretação do STF exige avaliação judicial dos fundamentos e admite prorrogação concretamente motivada.', 'Qual mudança de 2026 exige atenção no §1º? A previsão de custódia por videoconferência, com prazo de 24 horas, participantes e requisitos legais.', 'O acesso da defesa autoriza divulgar antecipadamente toda diligência ainda em execução? Não; distinguir elementos produzidos de diligências em andamento.'],
 [('Oferecimento','Apresentação da acusação; distinto da decisão judicial de recebimento.'),('Reserva de jurisdição','Restrição de direito que exige autorização judicial nas hipóteses legais.')],
 [STF,CNJ,CJF,'https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2026/lei/l15358.htm','https://web.trf3.jus.br/acordaos/Acordao/BuscarDocumentoPje/362788890','https://noticias.stf.jus.br/postsnoticias/stf-retoma-debates-sobre-a-lei-antifaccao/'])
add('3-c','A divisão de funções exige identificar quais processos seguem o juiz das garantias e o momento de passagem ao juiz da instrução. STF e CNJ corrigem a leitura isolada da redação compilada.',
 ['Marco constitucional: OFERECIMENTO da denúncia, não seu recebimento.', 'Questões pendentes passam ao juiz da instrução e julgamento.', 'Medidas cautelares não vinculam o juiz da instrução; necessidade reexaminada em até dez dias após a passagem dos autos.', 'Autos devem ser remetidos ao juiz da instrução: não ensinar retenção absoluta do inquérito na secretaria nem acesso apenas às provas irrepetíveis.', 'CNJ 562, art. 3º: fora dessa sistemática estão competência originária dos tribunais, Júri, violência doméstica/familiar das Leis 11.340 e 14.344, Juizados Especiais Criminais e varas criminais colegiadas do art. 1º-A da Lei 12.694. A exclusão não elimina audiência de custódia.'],
 ['Redação literal sobre recebimento e retenção dos autos não deve virar exercício automático de regra atual. Integrar ADIs 6298 e conexas e normas organizacionais.', 'Não inferir que todo processo penal em qualquer justiça segue a mesma organização, nem certificar implantação uniforme em todos os tribunais.'],
 'O MP oferece denúncia e ainda há pedido cautelar pendente: a competência passa ao juiz da instrução, que decide o pedido e reavalia as medidas em curso dentro do prazo aplicável.',
 'Em processo do Júri, não aplicar a divisão ordinária automaticamente: a hipótese está entre as exceções, sem dispensar controle da prisão e custódia.',
 ['O recebimento é o marco atual da competência do juiz das garantias? Não; o STF fixou o oferecimento.', 'Excluir o Júri da sistemática dispensa audiência de custódia? Não; a exclusão não elimina essa garantia.', 'O juiz da instrução fica vinculado às cautelares anteriores? Não; reexamina sua necessidade.'],
 [('Cisão funcional','Divisão de competências entre controle da investigação e instrução/julgamento.')],[STF,CNJ,CJF])
add('3-d','O artigo contém regra literal de impedimento e rodízio, mas o STF declarou inconstitucionais o caput e o parágrafo único. A implementação do juiz das garantias depende da organização judiciária e das diretrizes atuais.',
 ['Caput: inconstitucionalidade material reconhecida pelo STF.', 'Parágrafo único: inconstitucionalidade formal; organização judiciária compete aos respectivos tribunais.', 'CNJ 562 admite especialização, regionalização e substituição pré-definida, segundo os requisitos de cada modelo.'],
 ['Não criar flashcard afirmando que qualquer ato investigativo gera esse impedimento específico automaticamente ou que vara única deve sempre adotar rodízio.', 'Isso não elimina as demais regras de impedimento, suspeição e imparcialidade: analisar seus fundamentos próprios.'],
 'A comarca possui vara única e organiza atuação regional do juiz das garantias segundo normas do tribunal. Não exigir rodízio só pelo parágrafo declarado inconstitucional.',
 'Se há outra causa legal de impedimento ou suspeição, examiná-la autonomamente; a decisão sobre o art. 3º-D não dá licença para juiz parcial.',
 ['O rodízio do parágrafo único é imposição universal vigente? Não; o STF declarou inconstitucionalidade formal.', 'A decisão sobre o art. 3º-D elimina toda hipótese de suspeição? Não; as demais normas têm aplicação própria.'],
 [('Organização judiciária','Estrutura e distribuição institucional de funções, sujeitas às competências constitucionais.')],[CJF,CNJ,STF])
add('3-e','A função de juiz das garantias deve observar investidura e critérios objetivos da organização judiciária. A palavra designado no texto compilado não autoriza escolha discricionária de um magistrado para um caso específico.',
 ['STF: investir segundo normas de organização, com critérios objetivos periodicamente divulgados.', 'Promoção e remoção observam os critérios legais pertinentes.', 'CNJ: substituição pré-definida, juízes investidos e lista publicizada; modelo subsidiário quando inviáveis especialização/regionalização.'],
 ['Não confundir transparência dos critérios com liberdade de selecionar ad hoc o juiz de uma investigação. Preservar o juiz natural e regras de distribuição.'],
 'O tribunal publica critérios objetivos e organiza a unidade de garantias conforme sua legislação, sem escolher o julgador por interesse no caso.',
 'Indicar informalmente um juiz depois de saber quem será investigado não se legitima apenas pela palavra designado do art. 3º-E.',
 ['Pode haver escolha discricionária do juiz para favorecer um resultado? Não; exige investidura e critérios objetivos.', 'Critérios de atuação devem ficar secretos para a administração? Não; sua divulgação integra a disciplina constitucional e organizacional.'],
 [('Investidura','Exercício da função segundo normas de organização e critérios objetivos, não escolha casuística.')],[CNJ,CJF,STF])
add('3-f','O juiz das garantias deve impedir acordos ou ajustes de autoridades com a imprensa para explorar a imagem da pessoa presa. Informação pública e liberdade de imprensa devem conviver com dignidade, integridade e efetividade da persecução.',
 ['Proibição alcança acordo/ajuste para exploração da imagem da pessoa presa.', 'Responsabilidades civil, administrativa e penal dependem dos fundamentos e procedimentos aplicáveis.', 'Informação sobre prisão/autoria deve ser disciplinada com padronização, dignidade, efetividade e direito à informação.', 'O prazo de 180 dias do parágrafo é dirigido à regulamentação; não é prazo de exposição ou incomunicabilidade de um preso.'],
 ['Não ensinar proibição de toda notícia de prisão ou autorização de espetáculo vexatório. A responsabilização penal não é condenação automática sem tipo e processo.'],
 'Uma autoridade combina com a imprensa apresentação humilhante da pessoa presa para produzir imagens. O controle deve impedir essa exploração e apurar responsabilidades cabíveis.',
 'Comunicação institucional padronizada, pertinente e respeitosa sobre uma prisão não é automaticamente o ajuste vedado; verificar conteúdo, finalidade, dignidade e direitos.',
 ['O artigo proíbe qualquer informação pública sobre uma prisão? Não; exige compatibilização com dignidade e efetividade.', 'Os 180 dias são prazo de prisão incomunicável? Não; referem-se à regulamentação do procedimento informativo.'],
 [('Exploração da imagem','Uso acordado da imagem da pessoa presa vedado pelo dispositivo, sem confundir com informação pública legítima.')],[STF,CNJ])
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'CPP foundation units explicitly authored')
